function go(dest,opts={}){
  if(!PAGES[dest])return;
  if(dirty&&page==='editar'&&!opts.force&&dest!=='foto'){ask('Sair sem salvar?','Suas alterações ainda não foram aplicadas ao perfil.','Descartar alterações',()=>{dirty=false;state.profileDraft=null;go(dest,{force:true});});return;}
  if(page==='reforco'&&dest==='exercicio'){state.selected=state.originalAnswer??null;delete state.originalAnswer;}
  if(page!==dest){material?.onNavigate?.(page,dest);personal?.onNavigate?.(page,dest);}
  if(dest==='exercicio'){if(lessonIndex()>0)opts.f='multipla';else if(!opts.f)opts.f=state.exerciseFormat||'lacuna';state.exerciseFormat=opts.f;}
  if(recording){recording=false;clearInterval(recordInterval);state.explanation=recordDraft;}
  clearGeneration();const u=new URL(location.href);u.searchParams.set('p',dest);u.searchParams.delete('s');u.searchParams.delete('f');
  if(opts.s)u.searchParams.set('s',opts.s);if(opts.f)u.searchParams.set('f',opts.f);
  const index=history.state?.studoo?history.state.index:0;
  history.replaceState({studoo:true,index,page,scenario,format,scroll:document.querySelector('.app-main')?.scrollTop||0},'');
  history.pushState({studoo:true,index:index+1,page:dest,scenario:opts.s||'',format:opts.f||'lacuna',scroll:0},'',u);page=dest;scenario=opts.s||'';format=opts.f||'lacuna';saved();render(true);
}
function ask(h,text,confirm,cb,destructive=false,typed=false){
 const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<h2 id="dialog-title">${h}</h2><p>${text}</p>${typed?'<label class="field-label" for="confirm-delete">Digite EXCLUIR para confirmar</label><input id="confirm-delete" class="field" autocomplete="off">':''}${btn(confirm,'confirm-dialog',destructive?'primary danger-action':'primary')}${btn('Cancelar','cancel-dialog','quiet')}`;d.setAttribute('aria-labelledby','dialog-title');root.append(d);let opener=document.activeElement;
 d.querySelector('[data-action=confirm-dialog]').onclick=()=>{if(typed&&d.querySelector('input').value!=='EXCLUIR'){d.querySelector('input').setAttribute('aria-invalid','true');d.querySelector('input').focus();return;}d.close();d.remove();cb();};
 d.querySelector('[data-action=cancel-dialog]').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();if(opener?.isConnected)opener.focus();});d.showModal();d.querySelector(typed?'input':'[data-action=cancel-dialog]').focus();
}
