 if(page==='proposta'&&scenario==='falha-abrir')return {html:title('Sua trilha','O caminho está guardado.','No exemplo, a abertura da primeira lição falhou. Seu aceite e o progresso não precisam ser refeitos.')+note('Você pode tentar abrir a lição novamente ou voltar ao mapa.','book'),foot:actionButtons(btn('Abrir a primeira lição','open-first-after-failure'),btn('Ver mapa da trilha','go:mapa','quiet'))};
 if(page==='geracao'&&['erro','rede','ia-indisponivel','limite'].includes(scenario))return {html:title('Seu objetivo continua aqui',scenario==='limite'?'Este pedido atingiu um limite.':scenario==='ia-indisponivel'?'O apoio de IA está indisponível.':'A geração foi interrompida.',scenario==='limite'?'Você pode ajustar o objetivo ou tentar novamente depois. Nenhuma trilha foi adicionada.':'Não foi possível terminar a proposta. Você pode repetir ou voltar ao objetivo sem perder o texto.')+note('Falha simulada. IA e email permanecem falsos nesta bancada.','info')+`<div class="panel"><h2>Seu objetivo</h2><p>${esc(state.goal)}</p></div>`,foot:actionButtons(btn('Tentar gerar novamente','retry-scenario'),btn('Voltar ao objetivo','cancel-generation','quiet'))};
 if(page==='geracao'&&['longa','espera-longa','parcial'].includes(scenario)){const prior=scenario;if(scenario==='longa')scenario='espera-longa';const result=generationContent();scenario=prior;return result;}
 if(page==='explique'&&['erro','rede','envio-erro','enviando'].includes(scenario))return {html:`<div class="feedback incorrect" role="alert"><h2>${icon('info')}Sua explicação continua aqui.</h2><p>O envio de exemplo não foi confirmado. Revise o texto e tente novamente ou conclua sem explicar.</p></div>`+html,foot:actionButtons(btn('Tentar enviar de novo','send-explanation'),btn('Concluir sem explicar','complete','quiet')+btn('Etapa anterior','go:exercicio','quiet'))};

