function render(focusHeading=false){
 const active=document.activeElement,oldScroll=root.querySelector('.app-main')?.scrollTop||0;
 let restore=null,restoreIndex=0;if(active&&root.contains(active)){for(const k of ['action','go','choice','interest','hue','visibility','toggle','lesson']){if(active.dataset[k]!==undefined){restore=`button[data-${k}="${CSS.escape(active.dataset[k])}"]`;break;}}if(active.id)restore='#'+CSS.escape(active.id);if(restore)restoreIndex=Math.max(0,[...root.querySelectorAll(restore)].indexOf(active));}
 document.documentElement.dataset.reduced=state.settings.movimento?'true':'false';
 const {html,foot,active:activeNav}=mainPage();root.innerHTML=topbar()+`<main class="app-main" id="main"><section class="screen${focusHeading?' screen-enter':''}" data-page="${page}" aria-label="${PAGES[page]}">${html}</section></main>`+foot+(activeNav?nav(activeNav):'');
 const u=new URL(location.href);u.searchParams.set('p',page);if(scenario)u.searchParams.set('s',scenario);else u.searchParams.delete('s');if(page==='exercicio'&&format!=='lacuna')u.searchParams.set('f',format);else u.searchParams.delete('f');
 const index=history.state?.studoo?history.state.index:0;const entry={studoo:true,index,page,scenario,format,scroll:focusHeading?0:oldScroll};
 try{history.replaceState(entry,'',u);}catch{}renderedURL=location.href;renderedState=entry;
 document.title=`${PAGES[page]} · ${direction==='jornada'?'Jornada Azul':direction==='caderno'?'Caderno Claro':'Foco Vivo'} · Studoo`;
 if(focusHeading)root.querySelector('h1')?.focus({preventScroll:true});else{root.querySelector('.app-main').scrollTop=oldScroll;if(restore)root.querySelectorAll(restore)[restoreIndex]?.focus({preventScroll:true});}
 positionToast();
 if(window.parent!==window)window.parent.postMessage({type:'studoo-page',page,direction,scenario,format},location.protocol==='file:'?'*':location.origin);
}
function error(text,id='form-message'){const e=document.getElementById(id);if(e)e.innerHTML=`<p class="form-error">${esc(text)}</p>`;else notify(text);}
function focusExerciseAttempt(){
 const screen=root.querySelector('.screen[data-page="exercicio"]');if(!screen)return;
 const target=format==='associar'?screen.querySelector('select:not([disabled])'):format==='aberta'?screen.querySelector('#open-answer'):format==='ordenar'?screen.querySelector('[data-action="move-down-0"]'):format==='verdadeiro'&&state.selected==='v'&&(state.reason||'').trim().length<8?screen.querySelector('#reason'):screen.querySelector('.choice.selected')||screen.querySelector('.choice');
 (target||root.querySelector('.bottom-actions button.primary:not([disabled])'))?.focus();
}
function changeScenario(s){scenario=s;const u=new URL(location.href);if(s)u.searchParams.set('s',s);else u.searchParams.delete('s');history.replaceState({...history.state,page,scenario,format},'',u);saved();render();}
function beginGeneration(){clearGeneration();generationStep=0;go('geracao');if(q.get('capture')==='1')return;const run=generationRun;for(const [delay,step]of [[300,1],[650,2],[1100,3]])generationTimers.push(setTimeout(()=>{if(run!==generationRun||page!=='geracao')return;generationStep=step;render(false);},delay));generationTimers.push(setTimeout(()=>{if(run===generationRun&&page==='geracao')go('proposta');},1600));}
function selectedAnswerCorrect(){if(lessonIndex()>0)return state.selected===course[lessonIndex()].correct;if(format==='lacuna')return state.selected==='>=';if(format==='multipla')return state.selected==='bc';if(format==='ordenar')return state.order.join('|')==='Ler a tabela|Filtrar as linhas|Selecionar as colunas';if(format==='associar')return state.pairs.gt==='>'&&state.pairs.gte==='>='&&state.pairs.lte==='<=';if(format==='verdadeiro')return state.selected==='v'&&(state.reason||'').trim().length>=8;return openCriteria().every(x=>x.pass)&&(state.openAnswer||'').trim().length>=15;}
